using NUnit.Framework;
using SousTension.Spikes.MovingFrame.EditorTools;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;

namespace SousTension.Spikes.MovingFrame.Tests
{
    /// <summary>The spike can be launched (E1-11): the scene exists, is generated by code, and boots the game through the bootstrap.</summary>
    public class MovingFramePlayableSceneTests
    {
        [Test]
        public void TheScene_CanBeRegeneratedByCode_AndExists()
        {
            PlayLocal.CreateScene();
            Assert.IsNotNull(AssetDatabase.LoadAssetAtPath<SceneAsset>(PlayLocal.ScenePath), "scene asset missing: " + PlayLocal.ScenePath);
        }

        [Test]
        public void TheScene_ContainsTheBootstrap_AMainCamera_AndALight()
        {
            if (AssetDatabase.LoadAssetAtPath<SceneAsset>(PlayLocal.ScenePath) == null) PlayLocal.CreateScene();
            var scene = EditorSceneManager.OpenScene(PlayLocal.ScenePath, OpenSceneMode.Additive);
            try
            {
                bool bootstrap = false, camera = false, light = false;
                foreach (var root in scene.GetRootGameObjects())
                {
                    if (root.GetComponent<MovingFrameBootstrap>() != null) bootstrap = true;
                    if (root.GetComponent<UnityEngine.Camera>() != null) camera = true;
                    if (root.GetComponent<UnityEngine.Light>() != null) light = true;
                }
                Assert.IsTrue(bootstrap, "the scene has no MovingFrameBootstrap: Play would show nothing");
                Assert.IsTrue(camera, "no camera"); Assert.IsTrue(light, "no light");
            }
            finally { EditorSceneManager.CloseScene(scene, true); }
        }

        [Test]
        public void SpikePrimitives_UseUrpMaterials_NotTheBuiltInStandardOneThatTurnsEverythingPink()
        {
            PlayLocal.EnsureMaterials();
            var go = SpikePrimitives.Create(UnityEngine.PrimitiveType.Cube);
            try
            {
                var shader = go.GetComponent<UnityEngine.Renderer>().sharedMaterial.shader;
                Assert.AreEqual("Universal Render Pipeline/Lit", shader.name, "a Standard material is drawn pink by URP");
                Assert.IsTrue(shader.isSupported);
            }
            finally { UnityEngine.Object.DestroyImmediate(go); }
            var water = SpikePrimitives.Water();
            Assert.IsNotNull(water);
            Assert.AreEqual("Universal Render Pipeline/Unlit", water.shader.name);
            Assert.AreEqual((int)UnityEngine.Rendering.RenderQueue.Transparent, water.renderQueue, "the water is transparent");
        }

        [Test]
        public void NoViewCreatesAPrimitiveWithTheDefaultMaterial()
        {
            var views = System.IO.Directory.GetFiles("Assets/_Spikes/MovingFrame/Views", "*.cs");
            foreach (var path in views)
            {
                if (path.EndsWith("SpikePrimitives.cs")) continue;
                StringAssert.DoesNotContain("GameObject.CreatePrimitive(", System.IO.File.ReadAllText(path), path + " must use SpikePrimitives.Create (URP material)");
            }
        }

        [Test]
        public void TheLocalServer_HealthUrl_IsTheNakamaOneOfTheCompose()
        {
            StringAssert.Contains(":7350/", PlayLocal.HealthUrl);
        }
    }
}
